CREATE TABLE s_integrations(id TEXT PRIMARY KEY,label TEXT NOT NULL,owner_id TEXT NOT NULL,digest TEXT NOT NULL UNIQUE,scopes TEXT NOT NULL,matter_ids TEXT NOT NULL,endpoint TEXT,event_types TEXT NOT NULL,secret_sealed TEXT,enabled_at TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,paused INTEGER NOT NULL DEFAULT 0,failure_count INTEGER NOT NULL DEFAULT 0,generation INTEGER NOT NULL DEFAULT 1);
CREATE TABLE s_integration_requests(integration_id TEXT NOT NULL REFERENCES s_integrations(id),request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(integration_id,request_key));
CREATE TABLE s_integration_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,matter_id TEXT,object_id TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE s_webhook_deliveries(integration_id TEXT NOT NULL REFERENCES s_integrations(id),event_id TEXT NOT NULL REFERENCES s_integration_events(id),status TEXT NOT NULL DEFAULT 'queued',claim TEXT,lease_until TEXT,PRIMARY KEY(integration_id,event_id));
CREATE TABLE s_webhook_attempts(sequence INTEGER PRIMARY KEY AUTOINCREMENT,integration_id TEXT NOT NULL,event_id TEXT NOT NULL,at TEXT NOT NULL,outcome TEXT NOT NULL,http_status INTEGER);
CREATE TRIGGER s_webhook_attempts_no_update BEFORE UPDATE ON s_webhook_attempts BEGIN SELECT RAISE(ABORT,'webhook journal is append-only'); END;
CREATE TRIGGER s_webhook_attempts_no_delete BEFORE DELETE ON s_webhook_attempts BEGIN SELECT RAISE(ABORT,'webhook journal is append-only'); END;
CREATE TRIGGER s_integration_events_no_update BEFORE UPDATE ON s_integration_events BEGIN SELECT RAISE(ABORT,'integration events are append-only'); END;
CREATE TRIGGER s_integration_events_no_delete BEFORE DELETE ON s_integration_events BEGIN SELECT RAISE(ABORT,'integration events are append-only'); END;
CREATE TRIGGER s_integration_matter_created AFTER INSERT ON s_matters BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'matter.created',NEW.id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_matter_updated AFTER UPDATE ON s_matters BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'matter.updated',NEW.id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_task_created AFTER INSERT ON s_tasks BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'task.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_task_updated AFTER UPDATE ON s_tasks BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'task.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_document_updated AFTER UPDATE ON s_documents WHEN NEW.current_version>0 BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'document.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_deadline_created AFTER INSERT ON s_deadlines BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'deadline.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_deadline_updated AFTER UPDATE ON s_deadlines BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'deadline.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_bill_created AFTER INSERT ON s_bills BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_bill_updated AFTER UPDATE ON s_bills BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_entry_created AFTER INSERT ON s_entries BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_trust_created AFTER INSERT ON s_trust_entries WHEN NEW.ledger_id IS NOT NULL BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',(SELECT matter_id FROM s_trust_ledgers WHERE id=NEW.ledger_id),NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_proposal_decided AFTER UPDATE ON s_proposals WHEN NEW.status<>OLD.status BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'proposal.decided',COALESCE(json_extract(NEW.payload,'$.matterId'),CASE WHEN NEW.kind='matter' THEN NEW.result_id END),NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
